from wd_common import *
i=2
Z=lambda q,a:[('z',q),('b',a)]
def ladoo(): return '<circle r="14" fill="#e9a23a"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="2" fill="#c97a1a"/>' for x,y in [(-6,-4),(4,-8),(6,4),(-4,6)])
def leafplate(food='<circle r="10" fill="#f4f1ea"/>'): return '<ellipse rx="40" ry="10" fill="#2f8a3a"/>'+g(0,-6,1,food)
def cupped(): return '<path d="M-26 0 q0 -24 26 -24 q26 0 26 24z" fill="#e8c3a0"/>'
def potc(): return '<ellipse rx="20" ry="16" cy="-16" fill="#a0522d"/><ellipse cy="-30" rx="12" ry="4" fill="#5a2a10"/>'
fw=foreword(i,['Food is cooked, set before the god, offered with a prayer, and then comes back to us changed: it is now <b>prasāda</b>, the god’s grace in a form we can eat. A spoon of sweet rice, a laḍḍu from Tirumala, a drop of holy water, a pinch of ash: all are prasāda.',
 'This part explains the word, how offering becomes prasāda, what the Gītā says, how to receive and share it, the forms it takes, famous temple prasādas and the great tradition of feeding (annadāna).',
 'Previous: '+L('/why-do-we/tilaka/','tilaka')+'. Next: '+L('/why-do-we/coconut/','the coconut')+'. Offering at home: '+L('/home-puja/','Home Pūjā')+'.'],Z('Does the god actually eat?','Tradition says he accepts the essence. What comes back is the same food, but no longer just food.'))
gl=glance([('Word','Prasāda: grace, favour, clarity'),('Before','Naivedya: food offered to the deity'),('After','Prasāda: the offering returned as blessing'),('Forms','Food, holy water (tīrtha), ash, kuṅkuma, flowers, sandal'),('Scripture','Bhagavad Gītā 9.26 and 3.13, among others'),('Receiving','Right hand or both hands, with respect'),('Rule','Never refused, wasted or thrown away'),('Sharing','Given to family, friends, all comers'),('Famous','Tirumala laḍḍu, Puri mahāprasāda, Uḍupi anna-prasāda'),('Annadāna','Feeding devotees as prasāda')],
 S('Food on a leaf before a deity, then handed to devotees',g(160,215,1.4,god('#e0a800'))+g(160,215,1,leafplate())+'<path d="M220 160 C260 120 320 120 360 160" stroke="#e0a800" stroke-width="3" fill="none" marker-end=""/>'+g(420,215,1.3,person('#c0392b'))+g(420,170,.8,cupped()),'#fff3cf',215),Z('So the same food has two names?','Before offering, naivedya. After, prasāda. The difference is the god.'),'Offered, <b>then returned</b>.')
word=reading('word','THE WORD','Grace and clarity',S('A calm, clear lake under the sun',g(280,190,1,'<ellipse rx="220" ry="30" fill="#4aa3df"/>')+g(280,70,1,'<circle r="26" fill="#f0c030"/>'),'#d8e8f0',215),
 ['<b>Prasāda.</b> In Sanskrit, prasāda means grace, favour, kindness; also clearness and calm of mind.','<b>In the Gītā.</b> The Gītā uses prasāda for the peace of a mind at rest. (Bhagavad Gītā 2.64–65, sense.)','<b>Food.</b> In everyday use it means what is given back from worship.','<b>Regional words.</b> Kannaḍa prasāda, Hindi prasād, Tamiḻ pracātam; Śiva’s is sometimes called nirmālya.','<b>Both meanings meet.</b> The food is grace received; eating it with faith brings calm.'],Z('Grace and calm, in a sweet?','That is the idea. The sweet is the easy part.'),'Grace <b>you can taste</b>.')
offer=reading('offering','FROM NAIVEDYA TO PRASĀDA','How the offering is made',S('A cook preparing food without tasting; the food covered and set before the god; water sprinkled',g(130,215,1.3,person('#f4f1ea'))+g(180,190,1,potc())+g(380,215,1.3,god('#e0a800'))+g(380,215,1,leafplate())+'<path d="M330 150 l10 10 M340 145 l10 10" stroke="#4aa3df" stroke-width="3"/>','#fff3cf',215),
 ['<b>Cooked for the god.</b> Naivedya is cooked fresh and clean; by common custom the cook does not taste it first.','<b>Offered.</b> It is set before the deity, sprinkled with water, and offered with a prayer and a gesture.','<b>The pause.</b> A curtain may be drawn or a short time allowed; the god is believed to accept it.','<b>Returned.</b> What is taken back is now prasāda.','<b>Rules differ.</b> What may be offered (onion, garlic, meat) depends on the deity and the tradition.'],Z('Why not taste it?','You would be eating before the guest. In this house, the god eats first.'),'The god <b>eats first</b>.')
gita=reading('gita','WHAT THE GĪTĀ SAYS','A leaf, a flower, a fruit, water',S('Kṛṣṇa receiving a leaf, a flower, a fruit and water from a devotee',g(170,215,1.5,god('#1d4f8a'))+g(400,215,1.4,person('#c0392b'))+''.join(g(260+k*30,140,.6,f) for k,f in enumerate([leaf() if False else '<ellipse rx="8" ry="14" fill="#2f8a3a"/>',lotus('#e05050','#8e1f17'),'<circle r="9" fill="#e08a2a"/>','<path d="M-8 0 h16 l-3 -14 h-10z" fill="#4aa3df"/>'])),'#e3eaf3',215),
 ['<b>Gītā 9.26.</b> Kṛṣṇa says that whoever offers him with love a leaf, a flower, a fruit or water, he accepts it. (Sense, not a quotation.)','<b>Love, not cost.</b> The point is devotion, not the richness of the offering.','<b>Gītā 3.13.</b> Those who eat what remains of the offering are freed from fault; those who cook only for themselves eat sin. (Sense.)','<b>So, offer first.</b> Many families offer every meal before eating it, making all food prasāda.','<b>Read more.</b> The verses in full: '+L('/vishnu/bhagavad-gita/','Bhagavad Gītā')+'.'],Z('So my lunch can be prasāda?','Offer it first. That is the whole trick.'),'Offer with love; <b>eat what remains</b>.')
forms=cards('forms','FORMS OF PRASĀDA','Not only food',fig_row('A laddu, holy water, ash, kuṅkuma and a flower',[(ladoo(),1.3),('<path d="M-10 0 h20 l-4 -20 h-12z" fill="#4aa3df"/>',1.2),('<ellipse rx="16" ry="6" fill="#d9d4cc"/>',1.2),('<ellipse rx="16" ry="6" fill="#d02a2a"/>',1.2),(lotus('#e05050','#8e1f17'),.8)],['food','tīrtha','vibhūti','kuṅkuma','flowers'],gy=150),
 [('🍬','Food','Sweets, rice, fruit, pañcāmṛta.'),('💧','Tīrtha','Holy water from the abhiṣeka, sipped from the right palm.'),('⚪','Vibhūti','Sacred ash, worn on the forehead.'),('🔴','Kuṅkuma','Red powder from Devī worship.'),('🌸','Flowers','Flowers from the god, worn in the hair or kept.'),('🧵','Thread, cloth','A thread or cloth from the deity, worn or kept.')],None,'Grace <b>in many forms</b>.',intro='Whatever has touched the worship and comes back to the devotee is prasāda.')
recv=reading('receive','RECEIVING IT','Both hands, bowed head',S('A devotee receiving prasāda in cupped hands from a priest',g(200,215,1.5,person('#f4f1ea'))+g(360,215,1.5,person('#2a9d6f'))+g(290,160,1,cupped())+g(290,140,.7,ladoo()),'#fff3cf',215),
 ['<b>Right hand.</b> Prasāda is taken with the right hand, often resting on the left, or in both hands.','<b>Head bowed.</b> It is touched to the forehead or eyes before eating.','<b>Never refused.</b> Tradition holds that prasāda is never refused; take a little if you cannot take much.','<b>Never wasted.</b> It is not dropped, thrown away or left behind; leftovers are given to others, to cows or to water.','<b>No haste.</b> It is eaten with attention, not as a snack.'],Z('What if I am fasting?','Take it, touch it to your head, keep it for after. That is allowed.'),'Take grace <b>with both hands</b>.')
share=reading('share','SHARING','Prasāda is meant to be given',S('A family dividing prasāda among neighbours and children',g(280,190,1.2,ladoo())+''.join(g(80+k*100,215,1.1,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a'][k])) for k in range(5)),'#fff3cf',215),
 ['<b>Bring it home.</b> Pilgrims carry temple prasāda back for family and neighbours.','<b>Small pieces.</b> One laḍḍu can bless many people.','<b>No one excluded.</b> Prasāda is shared without asking who the eater is.','<b>Offered again.</b> At home it may first be placed in the family shrine.','<b>A bond.</b> Sharing prasāda makes the visit everyone’s.'],Z('Can I sell prasāda?','Temples sell it to cover costs. Selling it for profit is frowned on.'),'Grace <b>grows when shared</b>.')
famous=cards('temples','FAMOUS PRASĀDAS','Temples known for their food',fig_row('A laddu, clay pots, rice on a leaf and a dark sweet in a tin',[(ladoo(),1.4),(potc()+g(30,0,1,potc())+g(15,-30,1,potc()),.9),(leafplate(),1),('<rect x="-16" y="-24" width="32" height="24" fill="#9a9a9a"/><ellipse cy="-24" rx="16" ry="4" fill="#5a2a10"/>',1.1)],['Tirumala','Puri','Uḍupi','Sabarimala'],gy=150),
 [('🟠','Tirumala laḍḍu','The laḍḍu of Śrī Veṅkaṭeśvara, given to every pilgrim; see '+L('/temples-of-india/andhra-pradesh/tirumala/','Tirumala')+'.'),('🏺','Puri mahāprasāda','Jagannātha’s food, cooked in stacked clay pots; eaten by all castes together.'),('🍚','Uḍupi','Anna-prasāda served daily at the Kṛṣṇa maṭha; see '+L('/tulunadu/temples/udupi-srikrishna/','Uḍupi')+'.'),('🥫','Sabarimala','Aravaṇa pāyasam and appam of Ayyappa; see '+L('/temples-of-india/kerala/sabarimala/','Sabarimala')+'.'),('🍯','Pañcāmṛta','Five nectars (milk, curd, ghee, honey, sugar) after abhiṣeka.'),('🍛','Dharmasthaḷa','Free meals to all comers; see '+L('/tulunadu/temples/dharmasthala-manjunatha/','Dharmasthaḷa')+'.')],None,'Temples you can <b>taste</b>.')
anna=reading('annadana','ANNADĀNA','Feeding as worship',S('Long rows of people seated on the floor eating from leaves',''.join(g(70+k*70,200,.8,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800'][k%4],seat=True))+g(70+k*70,215,.6,leafplate()) for k in range(7)),'#fff3cf',215),
 ['<b>Annadāna.</b> The gift of food is praised in Hindu tradition as among the highest gifts.','<b>Temple kitchens.</b> Many temples feed thousands of devotees daily as prasāda.','<b>In rows.</b> Devotees sit together in rows (paṅkti) and eat from leaves.','<b>Karnataka.</b> Dharmasthaḷa, Uḍupi, Kukke and Horanāḍu are known for feeding all comers.','<b>Merit.</b> Donors give for anniversaries and vows, so the meal becomes their offering too.'],Z('Is temple lunch prasāda?','Yes. Cooked for the god, offered, then served: the whole meal is grace.'),'Feeding <b>is worship</b>.')
shiva=reading('nirmalya','A SPECIAL CASE','Offerings to Śiva',S('A Śiva liṅga with offerings and a small shrine of Caṇḍeśvara beside it',g(220,200,1.4,'<ellipse rx="44" ry="10" fill="#7a6a5a"/><rect x="-16" y="-56" width="32" height="56" rx="16" fill="#5a5a5a"/>')+g(400,200,1,god('#7a6a5a')),'#e3eaf3',215),
 ['<b>Nirmālya.</b> What is removed from a deity after worship is called nirmālya.','<b>A custom.</b> In some Śaiva traditions, food offered directly to the Śiva liṅga is not eaten by devotees, but given to <b>Caṇḍeśvara</b>, Śiva’s steward. (Traditions differ.)','<b>Elsewhere.</b> In many Śiva temples prasāda is distributed as usual.','<b>Ash and water.</b> Vibhūti and abhiṣeka water from Śiva are always taken as prasāda.','<b>Ask locally.</b> Each temple has its rule; follow it.'],Z('Why a special rule for Śiva?','Old Āgama customs differ. Follow the temple you are in.'),'Customs <b>differ by tradition</b>.')
st=story('story','THE LAST LAḌḌU','Meera shares the Tirumala laḍḍu',strip('Three panels: a girl gets a laḍḍu; she wants it all; she breaks it for everyone',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(60,180,.8,person('#c0392b'))+g(100,120,1,ladoo()),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,180,.8,person('#c0392b'))+g(72,110,1.2,ladoo()),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+''.join(g(30+k*40,180,.5,person(['#1d4f8a','#c0392b','#2a9d6f'][k])) for k in range(3))+''.join(g(30+k*40,120,.4,ladoo()) for k in range(3)),'#fff3cf')],['the gift','the temptation','the sharing']),'A family return from pilgrimage (an illustrative story).',
 ['Appa comes back from Tirumala with one big laḍḍu. Meera wants it all.','“It is the Lord’s,” says Amma. “He gave it to all of us.”','Meera breaks it: a piece for each, one for the neighbour, one for the shrine. It tastes better that way.'])
endp=end(i,['<b>Word.</b> Prasāda: grace, favour, calm.','<b>How.</b> Naivedya offered to the god becomes prasāda.','<b>Scripture.</b> Gītā 9.26 (offer with love) and 3.13 (eat what remains).','<b>Forms.</b> Food, tīrtha, ash, kuṅkuma, flowers.','<b>Way.</b> Received with respect, never wasted, always shared; annadāna.'],'Part 4 is the coconut.','Grace you can taste')
src=sources([('Practice:','Wikipedia, “Prasada” (meaning, naivedya, forms, temple examples); Bhagavad Gītā 2.64–65, 3.13, 9.26 (sense given, not quoted; see the site’s Gītā series for the text); temple practice at Tirumala, Puri, Uḍupi, Sabarimala and Dharmasthaḷa as described in the site’s temple guides.')],'the custom of not tasting naivedya, Caṇḍeśvara and nirmālya customs, and leftover disposal vary by tradition; meanings marked as interpretation are teachers’ readings.','No verse text is reproduced in this part.')
finish(i,'PART 3 OF 10 · NAIVEDYA · GRACE · ANNADĀNA',covart('Food on a leaf before a deity and a laḍḍu in cupped hands',g(140,190,1.1,god('#e0a800'))+g(140,190,.8,leafplate())+g(310,170,1.2,cupped())+g(310,150,.9,ladoo())),'Grace you can taste',
 'Why we take <b>prasāda</b>: the word, how naivedya becomes prasāda, what the <b>Gītā</b> says, how to receive and share it, famous temple prasādas and <b>annadāna</b>.',
 'Why do we take prasāda? Explained and illustrated: meaning, naivedya and offering, Gītā 9.26 and 3.13, forms of prasāda, receiving and sharing, Tirumala laḍḍu, Puri, Uḍupi, Sabarimala, annadāna and Śiva nirmālya customs.',
 [fw,gl,word,offer,gita,forms,recv,share,famous,anna,shiva,st,endp,src])
